contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint beforeBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEther = address(this).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint afterBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterEther = address(this).balance;

        assert(beforeBalance == amount && afterBalance == 0 && afterEther == beforeEther + amount);
    }

    receive() external payable {}
}

