contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 beforeBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint beforeEther = address(this).balance;
        try c.withdrawBalance() {} catch { return; }
        uint256 afterBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint afterEther = address(this).balance;
        assertTrue(beforeBalance == amount && afterBalance == 0 && afterEther == beforeEther + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
